const formatBM = (value: string): string => {
  if (!value) return "";
  const digits = value.replace(/\D/g, '').slice(0, 7);
  if (digits.length > 6) return `${digits.slice(0, 3)}.${digits.slice(3, 6)}-${digits.slice(6)}`;
  if (digits.length > 3) return `${digits.slice(0, 3)}.${digits.slice(3)}`;
  return digits;
};

const formatDateTime = (dateStr?: string) => {
  if (!dateStr) return "-";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(d);
  } catch { return dateStr; }
};

const formatDateOnly = (dateStr?: string) => {
  if (!dateStr) return "-";
  try {
    if (dateStr.length === 10 && dateStr.includes('-')) {
      const [y, m, d] = dateStr.split('-');
      return `${d}/${m}/${y}`;
    }
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' }).format(d);
  } catch { return dateStr; }
};

const isOverdue = (estimatedDate?: string, status?: MovementStatus) => {
  if (!estimatedDate || status === MovementStatus.DEVOLVIDO) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const estimate = new Date(estimatedDate);
  return estimate < today;
};

interface Notification {
  message: string;
  type: 'success' | 'error';
  id: number;
}

interface CartItem {
  id: string;
  material: string;
  reason: string;
  type: MaterialType;
  origin: string;
  estimatedReturn: string;
}

const App: React.FC = () => {
