        m.material || '', 
        m.bm || '', 
        m.reason || '',
        m.warName || '',
        m.receiverWarName || '',
        m.dutyOfficerName || '',
        m.origin || 'SAO' // Fix: Default to SAO so it matches displayed text for legacy items
      ].some(f => f.toLowerCase().includes(term));
      return matchesStatus && matchesSearch;
