    const email = `${toBm.replace(/\D/g, '')}@bombeiros.mg.gov.br`;
    try {
      await emailjs.send(
        EMAILJS_CONFIG.SERVICE_ID,
        EMAILJS_CONFIG.TEMPLATE_ID,
        {
          to_email: email,
          subject: subjectTitle,
          message: messageBody,
          content: messageBody
