    const newItem: CartItem = {
      id: Math.random().toString(36).substr(2, 9),
      material: checkoutMaterial,
      reason: checkoutReason || 'Não informado',
      type: checkoutType,
      origin: checkoutOrigin,
      estimatedReturn: checkoutEstimatedReturn
