            <p className="text-sm mb-6">Confirmar entrega de {checkoutCart.length} item(s) para o {borrowerRank} {borrowerName}?</p>
            <div className="flex gap-3">
              <button onClick={() => setShowCheckoutConfirm(false)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">REVISAR</button>
              <button onClick={handleCheckoutFinal} className="flex-1 py-4 bg-green-600 text-white rounded-xl font-bold">CONFIRMAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

