  const filteredMovements = useMemo(() => {
    const term = (searchTerm || '').toLowerCase();
    return movements.filter(m => {
      const matchesStatus = statusFilter === 'all' || m.status === statusFilter;
      // Fix for Error: Argument of type 'unknown' is not assignable to parameter of type 'string'.
      // Explicitly typing searchFields and applying fallbacks to guarantee string type for each element.
      const searchFields: string[] = [
        (m.name || ''), 
        (m.material || ''), 
        (m.bm || ''), 
        (m.reason || ''),
        (m.warName || ''),
        (m.receiverWarName || ''),
        (m.dutyOfficerName || ''),
        (m.origin || 'SAO')
      ];
      const matchesSearch = searchFields.some((f: string) => f.toLowerCase().includes(term));
      return matchesStatus && matchesSearch;
    });
  }, [movements, searchTerm, statusFilter]);

  if (showInstructions) {
    return (
      <div className="min-h-screen flex flex-col items-center p-4 bg-slate-50">
        <div className="w-full max-w-2xl bg-white rounded-3xl shadow-xl overflow-hidden animate-in fade-in slide-in-from-right duration-500">
           <div className="bg-slate-900 p-6 flex items-center justify-between text-white">
              <h2 className="text-xl font-bold uppercase tracking-wider flex items-center gap-3">
                <BookOpen className="w-6 h-6" /> Manual de Instruções
              </h2>
              <button 
                onClick={() => setShowInstructions(false)}
                className="bg-white/10 hover:bg-white/20 p-2 rounded-xl transition-all flex items-center gap-2 text-xs font-bold uppercase tracking-widest"
              >
                <ArrowLeft className="w-4 h-4" /> Voltar
              </button>
           </div>
           <div className="p-8 space-y-8 overflow-y-auto max-h-[80vh]">

              <section className="space-y-3">
                <h3 className="text-lg font-black uppercase text-red-700 flex items-center gap-2 border-b pb-2">
                  1. Login do Plantonista
                </h3>
                <p className="text-slate-600 text-sm leading-relaxed">
                  Apenas o <strong>Militar de serviço</strong> deve realizar o login. Os dados registrados identificam quem entregou ou recebeu os materiais. O nome de guerra é identificado se escrito em CAIXA ALTA (Ex: João SILVA).
                </p>
              </section>

              <section className="space-y-3">
                <h3 className="text-lg font-black uppercase text-red-700 flex items-center gap-2 border-b pb-2">
                  2. Cautela de Material (Saída)
                </h3>
                <ul className="list-disc pl-5 space-y-2 text-slate-600 text-sm">
                  <li>Identifique o militar retirante (BM e Nome).</li>
                  <li>Adicione os itens ao "carrinho" especificando a origem (SAO, Viatura, etc).</li>
                  <li>Finalize a cautela para disparar os e-mails de confirmação automáticos.</li>
                </ul>
              </section>

              <section className="space-y-3">
                <h3 className="text-lg font-black uppercase text-red-700 flex items-center gap-2 border-b pb-2">
                  3. Devolução (Entrada)
                </h3>
                <ul className="list-disc pl-5 space-y-2 text-slate-600 text-sm">
                  <li>Localize os itens na aba <strong>Devolução</strong>.</li>
                  <li>Selecione o que está sendo devolvido e clique em <strong>"Receber Itens"</strong>.</li>
                  <li>Registre avarias ou observações no campo de texto final.</li>
                </ul>
              </section>

              <section className="space-y-3">
                <h3 className="text-lg font-black uppercase text-red-700 flex items-center gap-2 border-b pb-2">
                  4. Histórico de Movimentações
                </h3>
                <p className="text-slate-600 text-sm leading-relaxed">
                  A aba <strong>Histórico</strong> é a central de consulta de todos os registros (ativos e finalizados).
                </p>
                <ul className="list-disc pl-5 space-y-2 text-slate-600 text-sm">
                  <li><strong>Barra de Busca:</strong> Permite localizar rapidamente por Nome de Guerra, BM, Descrição do Material ou Origem.</li>
                  <li><strong>Filtros Rápidos:</strong> Isole registros "Pendentes" (ainda com a tropa) ou "Devolvidos" (concluídos).</li>
                  <li><strong>Análise por IA:</strong> O botão "Analisar Carga" usa inteligência artificial para ler todo o histórico e gerar um relatório militar sobre atrasos e criticidade operacional.</li>
                </ul>
              </section>

              <section className="space-y-3">
                <h3 className="text-lg font-black uppercase text-red-700 flex items-center gap-2 border-b pb-2">
                  5. Modo Offline
                </h3>
                <p className="text-slate-600 text-sm leading-relaxed">
                  Se o Wi-Fi cair, o sistema continuará funcionando. Os dados serão salvos localmente e um ícone de "Sync Pendente" aparecerá. Clique no ícone de setas no topo para sincronizar quando a internet voltar.
                </p>
              </section>

              <div className="bg-slate-100 p-4 rounded-xl text-xs text-slate-500 font-medium text-center">
                Dúvidas técnicas? Procure o CBU ou a chefia da 1ª Cia.
              </div>
           </div>
        </div>
      </div>
    );
  }

  if (!authState.user) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-4 bg-slate-950 relative">
        <button onClick={() => setShowInstructions(true)} className="absolute top-6 right-6 text-slate-400 hover:text-white transition-colors flex items-center gap-2 group">
          <span className="text-[10px] uppercase font-bold tracking-widest opacity-0 group-hover:opacity-100 transition-opacity">Instruções de Uso</span>
          <div className="p-2 bg-white/5 rounded-full border border-white/10 group-hover:border-white/30">
            <BookOpen className="w-5 h-5" />
          </div>
        </button>
        <div className="w-full max-w-md bg-white rounded-3xl shadow-2xl overflow-hidden animate-in fade-in zoom-in-95 duration-500">
          <div className="bg-red-700 p-10 text-center text-white">
            <img src="https://www.bombeiros.mg.gov.br/images/logo.png" alt="Logo CBMMG" className="w-24 mx-auto mb-6 drop-shadow-xl" />
            <h1 className="text-4xl font-black uppercase tracking-tighter">SAO - 6º BBM / SEDE</h1>
          </div>
          <div className="p-8">
            <form onSubmit={async (e) => {
              e.preventDefault();
              const names = formName.trim().split(/\s+/);
              const uppercaseWords = names.filter(n => n === n.toUpperCase() && n.length >= 2);
              const warNameFound = uppercaseWords.length > 0 ? uppercaseWords.join(' ') : names[names.length - 1];
              const user: MilitaryPerson = { rank: formRank, name: formName, warName: warNameFound, bm: formBm, cpf: '' };
              setAuthState({ user, isVisitor: false });
              localStorage.setItem('sao_current_user', JSON.stringify(user));
              await syncData(true);
            }} className="space-y-5">
              <select className="w-full px-4 py-3 bg-slate-50 border rounded-xl" value={formRank} onChange={(e) => setFormRank(e.target.value)} required>
                <option value="">Selecione Posto/Grad...</option>
                {RANKS.map(r => <option key={r} value={r}>{r}</option>)}
              </select>
              <input type="text" placeholder="Nome Completo (GUERRA em CAIXA ALTA)" className="w-full px-4 py-3 bg-slate-50 border rounded-xl" value={formName} onChange={(e) => setFormName(e.target.value)} required />
              <input type="text" placeholder="Nº BM" className="w-full px-4 py-3 bg-slate-50 border rounded-xl" value={formBm} onChange={(e) => setFormBm(formatBM(e.target.value))} required />
              <button type="submit" className="w-full bg-red-700 text-white font-bold py-4 rounded-xl uppercase tracking-widest">Acessar Sistema</button>
            </form>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 relative">
      <header className="bg-red-700 text-white shadow-lg p-4 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
            <img src="https://www.bombeiros.mg.gov.br/images/logo.png" alt="Logo CBMMG" className="w-8 h-8" />
            <div>
              <h1 className="font-black text-xl uppercase">SAO - 6º BBM</h1>
              <div className="text-[8px] font-bold uppercase opacity-80">{isOnline ? 'Online' : 'Offline'} {lastSync && `(${lastSync})`}</div>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={handleSyncManually} className="p-2 bg-white/10 rounded-xl"><RefreshCw className={`w-5 h-5 ${isSyncing ? 'animate-spin' : ''}`} /></button>
            <button onClick={() => { setAuthState({ user: null, isVisitor: false }); localStorage.removeItem('sao_current_user'); }} className="p-2 bg-white/10 rounded-xl"><LogOut className="w-5 h-5" /></button>
          </div>
        </div>
      </header>

      <main className="flex-1 max-w-7xl w-full mx-auto p-4 sm:p-8 space-y-6">
        <div className="flex bg-white rounded-2xl shadow-sm border p-1 sticky top-20 z-40">
          {[
            { id: 'checkout', icon: PlusCircle, label: 'Saída' },
            { id: 'checkin', icon: ArrowRightLeft, label: 'Devolução' },
            { id: 'history', icon: History, label: 'Histórico' }
          ].map(tab => (
            <button key={tab.id} onClick={() => setActiveTab(tab.id as any)} className={`flex-1 flex items-center justify-center gap-2 py-3 rounded-xl font-bold ${activeTab === tab.id ? 'bg-red-700 text-white' : 'text-slate-500'}`}>
              <tab.icon className="w-4 h-4" /> <span className="text-[10px] uppercase">{tab.label}</span>
            </button>
          ))}
        </div>

        <div className="animate-in fade-in slide-in-from-bottom-4 duration-500">
          {activeTab === 'checkout' && (
            <div className="bg-white rounded-3xl p-6 shadow-sm border">
               <h2 className="text-xl font-bold uppercase mb-8 flex items-center gap-2"><ClipboardList className="text-red-600" /> Registro de Saída</h2>
               <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-8">
                  <select className="p-3 border rounded-xl" value={borrowerRank} onChange={(e) => setBorrowerRank(e.target.value)}>
                    <option value="">Posto/Grad...</option>
                    {RANKS.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                  <input type="text" placeholder="Nº BM Retirante" className="p-3 border rounded-xl" value={borrowerBm} onChange={(e) => setBorrowerBm(formatBM(e.target.value))} />
                  <input type="text" placeholder="Nome Completo" className="p-3 border rounded-xl" value={borrowerName} onChange={(e) => setBorrowerName(e.target.value)} />
               </div>
               <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                  <form onSubmit={addItemToCart} className="space-y-4">
                    <textarea placeholder="Materiais..." className="w-full p-4 bg-slate-50 border rounded-2xl min-h-[100px]" value={checkoutMaterial} onChange={(e) => setCheckoutMaterial(e.target.value)} />
                    <div className="grid grid-cols-2 gap-4">
                      <input list="origins" placeholder="Origem" className="p-3 border rounded-xl" value={checkoutOrigin} onChange={(e) => setCheckoutOrigin(e.target.value)} required />
                      <datalist id="origins">
                        <option value="SAO" /><option value="ABTS 1033" /><option value="UR 5566" /><option value="UR 2088" />
                      </datalist>
                      <input type="date" className="p-3 border rounded-xl" value={checkoutEstimatedReturn} onChange={(e) => setCheckoutEstimatedReturn(e.target.value)} required />
                    </div>
                    <button type="submit" className="w-full bg-slate-800 text-white py-4 rounded-xl font-bold uppercase">Adicionar à Lista</button>
                  </form>
                  <div className="bg-slate-50 p-6 rounded-2xl border flex flex-col">
                    <h3 className="text-xs font-black uppercase mb-4">Itens Selecionados ({checkoutCart.length})</h3>
                    <div className="flex-1 overflow-y-auto space-y-2 mb-4">
                      {checkoutCart.map(item => (
                        <div key={item.id} className="bg-white p-3 rounded-lg border flex justify-between">
                          <span className="text-xs font-bold">{item.material}</span>
                          <button onClick={() => removeItemFromCart(item.id)}><X className="w-4 h-4 text-red-400" /></button>
                        </div>
                      ))}
                    </div>
                    <button onClick={() => setShowCheckoutConfirm(true)} disabled={checkoutCart.length === 0} className="w-full bg-green-600 text-white py-4 rounded-xl font-bold uppercase">Finalizar Registro</button>
                  </div>
               </div>
            </div>
          )}

          {activeTab === 'checkin' && (
            <div className="bg-white rounded-3xl p-6 shadow-sm border min-h-[400px]">
              <div className="flex justify-between items-center mb-6">
                <h2 className="text-xl font-bold uppercase">Devolução de Materiais</h2>
                <input type="text" placeholder="Buscar..." className="p-2 border rounded-xl text-xs" value={checkinSearchTerm} onChange={(e) => setCheckinSearchTerm(e.target.value)} />
              </div>
              <div className="space-y-3">
                {movements.filter(m => m.status === MovementStatus.PENDENTE).filter(m => 
                  [m.name, m.warName, m.material].some(f => (f || '').toLowerCase().includes(checkinSearchTerm.toLowerCase()))
                ).map(m => (
                  <div key={m.id} className="p-4 bg-slate-50 rounded-xl border flex items-center gap-4">
                    <input type="checkbox" checked={selectedReturnIds.includes(m.id)} onChange={() => toggleReturnSelection(m.id)} className="w-5 h-5" />
                    <div className="flex-1">
                      <div className="font-bold uppercase text-sm">{m.rank} {m.warName}</div>
                      <div className="text-[10px] text-slate-500 italic">{m.material}</div>
                    </div>
                  </div>
                ))}
              </div>
              {selectedReturnIds.length > 0 && (
                <button onClick={() => setShowReturnConfirm(true)} className="fixed bottom-10 right-10 bg-green-600 text-white p-6 rounded-full shadow-2xl font-bold uppercase">Receber Selecionados ({selectedReturnIds.length})</button>
              )}
            </div>
          )}

          {activeTab === 'history' && (
            <div className="space-y-6">
               <div className="bg-white rounded-3xl p-6 shadow-sm border">
                  <div className="flex gap-4 mb-6">
                    <input type="text" placeholder="Filtrar histórico..." className="flex-1 p-3 border rounded-xl" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                    <select className="p-3 border rounded-xl text-xs" value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as any)}>
                      <option value="all">Todos</option>
                      <option value={MovementStatus.PENDENTE}>Pendentes</option>
                      <option value={MovementStatus.DEVOLVIDO}>Devolvidos</option>
                    </select>
                  </div>
                  <div className="overflow-x-auto">
                    <table className="w-full text-left text-xs">
                      <thead><tr className="border-b uppercase text-slate-400 font-black">
                        <th className="p-3">Militar</th><th className="p-3">Material</th><th className="p-3">Saída</th><th className="p-3">Status</th>
                      </tr></thead>
                      <tbody>
                        {filteredMovements.map(m => (
                          <tr key={m.id} className="border-b hover:bg-slate-50">
                            <td className="p-3 font-bold uppercase">{m.rank} {m.warName}</td>
                            <td className="p-3">{m.material}</td>
                            <td className="p-3">{formatDateTime(m.dateCheckout)}</td>
                            <td className="p-3">
                              <span className={`px-2 py-1 rounded-full font-black text-[9px] ${m.status === 'PENDENTE' ? 'bg-amber-100 text-amber-700' : 'bg-green-100 text-green-700'}`}>{m.status}</span>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
               </div>
               <div className="bg-slate-900 rounded-3xl p-8 text-white">
                  <div className="flex justify-between items-center mb-6">
                    <h3 className="font-bold uppercase flex items-center gap-2"><Sparkles className="text-yellow-400" /> Relatório de Carga (IA)</h3>
                    <button onClick={async () => { setIsLoadingAi(true); const res = await getSmartSummary(movements); setAiSummary(res); setIsLoadingAi(false); }} disabled={isLoadingAi} className="bg-white text-black px-6 py-2 rounded-xl text-xs font-bold uppercase">Analisar</button>
                  </div>
                  {aiSummary && <div className="p-4 bg-white/5 rounded-xl text-sm leading-relaxed">{aiSummary}</div>}
               </div>
            </div>
          )}
        </div>
      </main>

      {showReturnConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-3xl p-8 shadow-2xl">
            <h3 className="text-xl font-bold uppercase mb-4 text-green-600">Confirmar Recebimento</h3>
            <textarea className="w-full p-4 border rounded-xl mb-6 min-h-[100px]" placeholder="Observações (opcional)..." value={pendingObservations} onChange={(e) => setPendingObservations(e.target.value)} />
            <div className="flex gap-3">
              <button onClick={() => setShowReturnConfirm(false)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">CANCELAR</button>
              <button onClick={handleReturnFinal} className="flex-1 py-4 bg-green-600 text-white rounded-xl font-bold">CONFIRMAR</button>
            </div>
          </div>
        </div>
      )}

      {showCheckoutConfirm && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm">
          <div className="bg-white w-full max-w-lg rounded-3xl p-8 shadow-2xl">
            <h3 className="text-xl font-bold uppercase mb-4 text-amber-600">Confirmar Saída</h3>
            <p className="text-sm mb-6">Confirmar entrega de {checkoutCart.length} item(s) para o {borrowerRank} {borrowerName}?</p>
            <div className="flex gap-3">
              <button onClick={() => setShowCheckoutConfirm(false)} className="flex-1 py-4 bg-slate-100 rounded-xl font-bold">REVISAR</button>
              <button onClick={handleCheckoutFinal} className="flex-1 py-4 bg-green-600 text-white rounded-xl font-bold">CONFIRMAR</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;
